/**
 * @suppress
 */
public object FfiConverterTypeFfiWorkspace: FfiConverter<FfiWorkspace, Pointer> {

    override fun lower(value: FfiWorkspace): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): FfiWorkspace {
        return FfiWorkspace(value)
    }

    override fun read(buf: ByteBuffer): FfiWorkspace {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: FfiWorkspace) = 8UL

    override fun write(value: FfiWorkspace, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



